SELECT p.payment_id, p.member_id, p.merchant_id, p.koces_cd, p.message_number, p.institution_code, p.transmission_date, p.trace_number, p.merchant_number, p.card_number, p.track_data, p.key_in, p.input_method, p.amount, p.transaction_type, p.approval_number, p.response_code, p.cancel_code, p.original_trade_date, p.original_approval_number, p.original_amount, p.remaining_point, p.filter_value, p.status, p.created_at, p.updated_at, COALESCE(m.merchant_name, p.merchant_name) AS merchant_name, m.business_number AS business_number, COALESCE(m.representative, p.representative) AS representative, COALESCE(m.contact, p.phone) AS phone, COALESCE(m.address, p.address) AS address, COALESCE(m.terminal_id, p.terminal_id) AS terminal_id, mb.name AS member_name, mb.birth_date AS birth_date, mb.gender AS gender FROM payment p LEFT JOIN merchant m ON p.merchant_id = m.merchant_id LEFT JOIN member mb ON p.member_id = mb.member_id LEFT JOIN merchant_category mc ON m.category_id = mc.category_id
AND p.status != 'DELETED'
AND p.transmission_date >= #{startDate}
AND p.transmission_date <= #{endDate}
AND p.transmission_date >= DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 3 MONTH), '%Y%m%d')
AND p.transaction_type = #{transactionType}
AND COALESCE(m.merchant_name, p.merchant_name) LIKE CONCAT('%', #{merchantName}, '%')
AND p.approval_number = #{approvalNumber}
AND p.merchant_id = #{merchantId}
AND p.status = #{status}
AND mb.name LIKE CONCAT('%', #{memberName}, '%')
AND p.member_id = #{memberId}
AND mc.category_name = #{tab}
AND p.card_number LIKE CONCAT('%', #{cardNumber}, '%')
ORDER BY CASE WHEN p.status = 'SUCCESS' THEN 0 ELSE 1 END ASC, p.created_at DESC, p.payment_id DESC LIMIT #{size} OFFSET #{offset}

SELECT COALESCE(SUM(p.amount), 0)
FROM payment p
LEFT JOIN merchant m  ON p.merchant_id = m.merchant_id
LEFT JOIN merchant_category mc ON m.category_id = mc.category_id  
LEFT JOIN member mb ON p.member_id = mb.member_id

    AND p.status != 'DELETED'

        AND p.transmission_date >= #{startDate}


        AND p.transmission_date <= #{endDate}


        AND p.transmission_date >= DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 3 MONTH), '%Y%m%d')


        AND p.merchant_id = #{merchantId}


        AND p.member_id = #{memberId}


        AND mc.category_name = #{tab}


        AND p.status = #{status}


        AND p.status = 'SUCCESS'   


        AND mb.name LIKE CONCAT('%', #{memberName}, '%')


        AND p.card_number LIKE CONCAT('%', #{cardNumber}, '%')

SELECT COUNT(*)
FROM payment p
LEFT JOIN merchant m  ON p.merchant_id = m.merchant_id
LEFT JOIN member   mb ON p.member_id   = mb.member_id
LEFT JOIN merchant_category mc ON m.category_id = mc.category_id

    AND p.status != 'DELETED'

        AND p.transmission_date >= #{startDate}


        AND p.member_id = #{memberId}


        AND mc.category_name = #{tab}


        AND p.transmission_date <= #{endDate}


        AND p.transmission_date >= DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 3 MONTH), '%Y%m%d')


        AND p.transaction_type = #{transactionType}


        AND COALESCE(m.merchant_name, p.merchant_name) LIKE CONCAT('%', #{merchantName}, '%')


        AND p.approval_number = #{approvalNumber}


        AND p.status = #{status}


        AND p.merchant_id = #{merchantId}


        AND mb.name LIKE CONCAT('%', #{memberName}, '%')


        AND p.card_number LIKE CONCAT('%', #{cardNumber}, '%')

