UPDATE payment
SET status = #{status}
WHERE payment_id = #{paymentId}
  AND transmission_date = #{transmissionDate}

UPDATE payment
SET status = 'DELETED'
WHERE payment_id = #{paymentId}
  AND transmission_date = #{transmissionDate}
